'use client';

import type React from 'react';
import {
  FormProvider,
  type Resolver,
  type UseFormProps,
  type UseFormReturn,
  useController,
  useFieldArray,
  useForm,
  useFormContext,
  useWatch,
} from 'react-hook-form';
import {
  type AutoFormArrayController,
  type AutoFormEngine,
  AutoFormEngineProvider,
  type AutoFormFieldController,
  useDirtyStateNotification,
} from '../engine';
import { getPathInObject } from '../field-utils';
import { getRootErrorMessage } from '../helpers';
import { PROTO_FORM_ROOT_ERROR_KEY } from '../proto';

type FormValues = Record<string, unknown>;

function ReactHookFormFieldController({
  children,
  name,
}: {
  children: (controller: AutoFormFieldController) => React.ReactNode;
  name: string;
}) {
  const form = useFormContext<FormValues>();
  const { field, fieldState } = useController<FormValues>({ name });
  const messages = [fieldState.error?.message, ...Object.values(fieldState.error?.types ?? {})].filter(
    (message): message is string => typeof message === 'string'
  );

  return children({
    errors: [...new Set(messages)],
    name: field.name,
    onBlur: field.onBlur,
    onChange: (value, options) => {
      if (options) {
        form.setValue(name, value, options);
        return;
      }
      field.onChange(value);
    },
    ref: (element) => field.ref(element),
    value: field.value,
  });
}

function ReactHookFormArrayController({
  children,
  name,
}: {
  children: (controller: AutoFormArrayController) => React.ReactNode;
  name: string;
}) {
  const form = useFormContext<FormValues>();
  const { append, fields, remove } = useFieldArray({
    control: form.control,
    name: name as never,
  });
  const values: unknown = getPathInObject(form.getValues(), name.split('.'));
  const items = fields.map((field, index) => ({
    key: field.id,
    value: Array.isArray(values) ? (values[index] as unknown) : undefined,
  }));

  return children({
    append: (value) => append(value),
    items,
    remove,
  });
}

function applyValidationErrors<T extends FormValues>(
  form: UseFormReturn<FormValues, unknown, T>,
  errors: Array<{ message: string; path: Array<string | number> }>
) {
  form.clearErrors();
  const rootMessages: string[] = [];
  let shouldFocus = true;

  const fieldMessages = new Map<string, string[]>();
  for (const error of errors) {
    if (error.path.length === 0) {
      rootMessages.push(error.message);
      continue;
    }

    const path = error.path.join('.');
    fieldMessages.set(path, [...(fieldMessages.get(path) ?? []), error.message]);
  }
  for (const [path, messages] of fieldMessages) {
    form.setError(
      path,
      {
        message: messages[0] ?? '',
        type: 'validation',
        types: Object.fromEntries(messages.map((message, index) => [String(index), message])),
      },
      { shouldFocus }
    );
    shouldFocus = false;
  }

  if (rootMessages.length > 0) {
    form.setError('root', {
      message: rootMessages.join('\n'),
      type: 'validation',
    });
  }
}

export interface ReactHookFormEngineProps<T extends FormValues> {
  children: (engine: AutoFormEngine) => React.ReactNode;
  defaultValues: FormValues;
  formOptions?: UseFormProps<FormValues, unknown, T> | undefined;
  onDirtyChange?: ((isDirty: boolean) => void) | undefined;
  resolver?: Resolver<FormValues, unknown, T> | undefined;
  values?: FormValues | undefined;
}

export function ReactHookFormEngine<T extends FormValues>({
  children,
  defaultValues,
  formOptions,
  resolver,
  values,
  onDirtyChange,
}: ReactHookFormEngineProps<T>) {
  const form = useForm<FormValues, unknown, T>({
    ...formOptions,
    defaultValues,
    ...(resolver ? { resolver } : {}),
    ...(values ? { values } : {}),
  });
  const watchedValues = (useWatch({ control: form.control }) as FormValues | undefined) ?? {};
  const errors = form.formState.errors as Record<string, unknown>;
  const rootMessage = getRootErrorMessage(form.formState.errors.root);
  const rootError =
    rootMessage !== undefined && rootMessage !== ''
      ? rootMessage
      : getRootErrorMessage(errors[PROTO_FORM_ROOT_ERROR_KEY]);
  const notifyDirtyChange = useDirtyStateNotification(form.formState.isDirty, onDirtyChange);

  const engine: AutoFormEngine = {
    ArrayController: ReactHookFormArrayController,
    clearErrors: (paths) => form.clearErrors(paths),
    defaultValues: form.formState.defaultValues,
    dirtyFields: form.formState.dirtyFields,
    errors,
    FieldController: ReactHookFormFieldController,
    focus: (path) => form.setFocus(path),
    getFieldInvalid: (path) => form.getFieldState(path).invalid,
    getValues: form.getValues,
    handleSubmit: (onValid) => form.handleSubmit(onValid),
    isDirty: form.formState.isDirty,
    isSubmitting: form.formState.isSubmitting,
    markClean: () => {
      form.reset(form.getValues());
      notifyDirtyChange(false);
    },
    nativeForm: form,
    reset: (nextValues, options) => form.reset(nextValues, options),
    rootError,
    setRootError: (message) => form.setError('root', { message, type: 'submit' }),
    setValidationErrors: (validationErrors) => applyValidationErrors(form, validationErrors),
    setValue: (path, value, options) => form.setValue(path, value, options),
    trigger: async (paths) => form.trigger(paths),
    validatesSchema: Boolean(resolver),
    values: watchedValues,
  };

  return (
    <FormProvider {...form}>
      <AutoFormEngineProvider engine={engine}>{children(engine)}</AutoFormEngineProvider>
    </FormProvider>
  );
}

'use client';

import { useRef, useSyncExternalStore } from 'react';
import { Form, type FormProps, useFormContext } from 'react-hook-form';
import type { AutoFormFormRenderProps } from '../auto-form-core';

type FormValues = Record<string, unknown>;

export type AutoFormSubmissionProps = Omit<FormProps<FormValues>, 'children' | 'control' | 'render'> & {
  [attribute: `data-${string}`]: string | number | boolean | undefined;
};

class RejectedAutoFormSubmissionError extends Error {
  override name = 'RejectedAutoFormSubmissionError';
}

function subscribeToHydration() {
  return () => undefined;
}

export function ReactHookFormSubmission({
  children,
  FormComponent,
  formProps,
  onSubmit,
  options,
}: AutoFormFormRenderProps & { options: AutoFormSubmissionProps }) {
  const form = useFormContext<FormValues, unknown, FormValues>();
  const inFlight = useRef<boolean>(false);
  const mounted = useSyncExternalStore(
    subscribeToHydration,
    () => true,
    () => false
  );

  function reportSubmissionError(error: unknown) {
    if (error instanceof RejectedAutoFormSubmissionError) {
      return;
    }
    form.setError('root', {
      message: error instanceof Error ? error.message : 'Submission failed.',
      type: 'submit',
    });
  }

  return (
    <Form
      {...options}
      control={form.control}
      onError={(error) => {
        reportSubmissionError(error.error ?? new Error('Submission failed.'));
        options.onError?.(error);
      }}
      onSubmit={async (payload) => {
        if (!(await onSubmit(payload.data)) || Object.keys(form.getErrors()).length > 0) {
          throw new RejectedAutoFormSubmissionError();
        }
        await options.onSubmit?.(payload);
        if (Object.keys(form.getErrors()).length > 0) {
          throw new RejectedAutoFormSubmissionError();
        }
      }}
      render={({ submit }) => (
        <FormComponent
          {...formProps}
          action={options.action}
          {...(typeof options.action === 'function'
            ? {}
            : { encType: options.encType, method: options.method ?? 'post' })}
          noValidate={options.noValidate ?? mounted}
          onSubmit={async (event) => {
            event.preventDefault();
            if (inFlight.current) {
              return;
            }
            inFlight.current = true;
            await Promise.resolve(submit(event))
              .catch(reportSubmissionError)
              .finally(() => {
                inFlight.current = false;
              });
          }}
        >
          {children}
        </FormComponent>
      )}
    />
  );
}

'use client';

import type React from 'react';
import type { Resolver, UseFormProps, UseFormReturn } from 'react-hook-form';
import { createProtoResolver } from '@/registry/base-nova/protoform/hooks/use-proto-form';
import { ReactHookFormEngine } from './adapters/react-hook-form';
import { type AutoFormSubmissionProps, ReactHookFormSubmission } from './adapters/react-hook-form-submission';
import { AutoFormCore } from './auto-form-core';
import { isProtoMessageDescriptor, isProtoProvider } from './proto';
import { protoConversionOptionsFromFieldConfig } from './schema';
import type { AutoFormValidationMode, AutoFormProps as BaseAutoFormProps } from './types';
import type { ProtoformUIComponentMap } from './ui-component-map';

type FormValues = Record<string, unknown>;

export type AutoFormProps<T extends FormValues = FormValues, TCustomFieldType extends string = never> = Omit<
  BaseAutoFormProps<
    T,
    UseFormReturn<FormValues, unknown, T>,
    UseFormProps<FormValues, unknown, T>,
    Resolver<FormValues, unknown, T>,
    TCustomFieldType
  >,
  'formProps'
> & { components: ProtoformUIComponentMap; formProps?: AutoFormSubmissionProps };

export type { AutoFormSubmissionProps } from './adapters/react-hook-form-submission';

function toHookFormMode(mode: AutoFormValidationMode): 'onBlur' | 'onChange' | 'onSubmit' {
  switch (mode) {
    case 'blur':
      return 'onBlur';
    case 'change':
      return 'onChange';
    case 'submit':
      return 'onSubmit';
    default:
      throw new TypeError(`Unsupported validation mode: ${mode satisfies never}`);
  }
}

export function AutoForm<T extends FormValues = FormValues, TCustomFieldType extends string = never>(
  props: AutoFormProps<T, TCustomFieldType>
): React.ReactNode;
export function AutoForm({
  components,
  formOptions,
  formProps,
  resolver,
  ...props
}: AutoFormProps<FormValues, string>) {
  let protoDescriptor = isProtoMessageDescriptor(props.schema) ? props.schema : undefined;
  if (!protoDescriptor && isProtoProvider(props.schema)) {
    protoDescriptor = props.schema.getMessageDescriptor();
  }
  const conversionOptions = {
    ...protoConversionOptionsFromFieldConfig(props.fieldConfig),
    formatMessage: props.formatMessage,
  };
  let resolvedResolver = resolver;
  if (!resolvedResolver && protoDescriptor) {
    resolvedResolver = formProps
      ? createProtoResolver(protoDescriptor, conversionOptions, undefined, { raw: true })
      : createProtoResolver(protoDescriptor, conversionOptions);
  }
  const htmlFormProps = { ...formProps };
  for (const name of ['action', 'encType', 'headers', 'method', 'onError', 'onSubmit', 'onSuccess', 'validateStatus']) {
    Reflect.deleteProperty(htmlFormProps, name);
  }
  const engineOptions: UseFormProps<FormValues, unknown, FormValues> = {
    ...formOptions,
    ...(props.validationMode
      ? {
          mode: toHookFormMode(props.validationMode),
        }
      : {}),
    ...(props.revalidationMode
      ? {
          reValidateMode: props.revalidationMode === 'change' ? 'onChange' : 'onBlur',
        }
      : {}),
  };

  return (
    <AutoFormCore<FormValues, UseFormReturn<FormValues, unknown, FormValues>, string>
      {...props}
      components={components}
      formProps={htmlFormProps}
      renderEngine={({ children, defaultValues, values }) => (
        <ReactHookFormEngine<FormValues>
          defaultValues={defaultValues}
          formOptions={engineOptions}
          onDirtyChange={props.onDirtyChange}
          resolver={resolvedResolver}
          values={values}
        >
          {children}
        </ReactHookFormEngine>
      )}
      renderForm={
        formProps ? (renderProps) => <ReactHookFormSubmission {...renderProps} options={formProps} /> : undefined
      }
    />
  );
}
